.vtown{font:800 17px "Schibsted Grotesk",system-ui,sans-serif;letter-spacing:-.01em;fill:#0E1430;paint-order:stroke;stroke:#FFFFFF;stroke-width:4px;stroke-linejoin:round;pointer-events:none}
